// golfing  748 / 591 chars  https://shadertoy.com/view/wtVyRW

void mainImage( out vec4 O,  vec2 u )
{
    vec2 R = iResolution.xy,
         U = (u+u-R)/R.y, P;      
    O*=0.;O++;

    for( int i=0; i < 9 * min( int( pow(1.-U.y,1.7) *R.y/13. ), 200); i++ )
        P =  round(U*11.) + vec2(i%3,(i/3)%3),
        P += fract( 4e4* sin( 1e2* ( mat2(10,71,51,23) * P + float(i/9) ) )) -1.5,
        O -= O * max( 0., .5 - abs( dot( P = U - P/11. , 
                                    normalize( sin( vec2(5,3)*U/2. + cos( U/2.*mat2(3,10,-4,1) ) ) ) 
                                  ))*R.y/4. )
               * clamp( ( .08 - length(P) ) *R.y ,0.,1.);

    O = sqrt( O + max(0., length(U)-.8 ) *R.y );
}
